import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

root = write_project('handle_contracts', '''
    use core.http;
    use core.proc;
    use core.storage;
    use core.thread;
    fn worker() -> i32 {
        return 1
    }
    fn main() -> i32 {
        let conn = http.accept()
        discard http.write_json(conn, 200, "{}")
        let stream = http.post_json_stream("https://example.com", "{}")
        discard http.stream_close(stream)
        let argv = proc.argv_new()
        let env = proc.env_new()
        let proc_handle = proc.spawn_cmd("echo", argv, env, "")
        discard proc.close(proc_handle)
        let task = spawn(worker)
        discard join(task)
        let store = storage.kv_open("session.kv")
        discard storage.kv_close(store)
        let payload = json.parse("{}")
        let entries = json.to_map(payload)
        discard map.len(entries)
        return 0
    }
''')
proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
payload = json.loads(proc.stdout.strip())
assert proc.returncode == 0 and payload['errors'] == 0, (proc.returncode, payload, proc.stderr)
handle_contracts = json.loads((root / '.fz' / 'handle-contracts.json').read_text())
runtime_contracts = json.loads((root / '.fz' / 'native-runtime-contracts.json').read_text())
handle_text = json.dumps(handle_contracts)
runtime_text = json.dumps(runtime_contracts)
assert 'HttpHandle' in handle_text and 'JsonHandle' in handle_text and 'KvStoreHandle' in handle_text, handle_contracts
assert 'http.write_json' in runtime_text and 'consume_arg0_borrow_status_payload' in runtime_text, runtime_contracts
assert 'json.parse' in runtime_text and 'produces_handle' in runtime_text, runtime_contracts
assert 'list.len' in runtime_text and 'observes_handle' in runtime_text, runtime_contracts
print('compiler-memory-handle-contracts-ok')

